def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        from datetime import datetime, timedelta, timezone
        from dateutil import tz as dateutil_tz
    except ImportError:
        from datetime import datetime, timedelta, timezone

    if nanoseconds is None:
        raise ValueError("nanoseconds cannot be None")

    if not isinstance(nanoseconds, (int, float)):
        raise TypeError("nanoseconds must be an integer or float")

    # Convert nanoseconds to seconds
    total_seconds = nanoseconds / 1e9

    # Create a datetime object from the epoch
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    dt = epoch + timedelta(seconds=total_seconds)

    if tz is not None:
        # If tz is a string, try to parse it
        if isinstance(tz, str):
            try:
                tz = dateutil_tz.gettz(tz)
            except Exception:
                raise ValueError(f"Invalid timezone: {tz}")
        # If tz is a timezone object, use it
        elif isinstance(tz, timezone):
            pass
        else:
            # Try to convert to a timezone object
            try:
                tz = dateutil_tz.gettz(tz)
            except Exception:
                raise ValueError(f"Invalid timezone: {tz}")

        # Convert the datetime to the specified timezone
        dt = dt.astimezone(tz)

    return dt

