def round_half_to_even(n):
    if n is None:
        raise ValueError("Input cannot be None")
    try:
        n = float(n)
    except (TypeError, ValueError):
        raise ValueError("Input must be a numeric value")

    if n == int(n):
        return int(n)

    floor_val = int(n)
    if n < 0:
        floor_val = int(n) - 1 if n != int(n) else int(n)

    remainder = n - floor_val
    if remainder < 0.5:
        return floor_val
    elif remainder > 0.5:
        return floor_val + 1
    else:
        # remainder is exactly 0.5
        if floor_val % 2 == 0:
            return floor_val
        else:
            return floor_val + 1

