def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            self.fields = {}
            for i, field in enumerate(fields):
                if i < len(args):
                    self.fields[field] = args[i]
                elif field in kwargs:
                    self.fields[field] = kwargs[field]
                else:
                    self.fields[field] = None
            self.srid = srid_map.get(name, None)

        def __repr__(self):
            field_strs = [f"{field}={self.fields[field]!r}" for field in fields]
            return f"{name}({', '.join(field_strs)})"

        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            return all(self.fields[field] == other.fields[field] for field in fields)

    Point.__name__ = name
    return Point

