def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        return last_applied_manifest
    if len(last_applied_manifest) != len(observer_schema) or len(last_applied_manifest) != len(response):
        return last_applied_manifest
    for i in range(len(last_applied_manifest)):
        schema_item = observer_schema[i]
        resp_item = response[i]
        manifest_item = last_applied_manifest[i]
        if isinstance(schema_item, list) and isinstance(resp_item, list):
            if not isinstance(manifest_item, list):
                last_applied_manifest[i] = []
                manifest_item = last_applied_manifest[i]
            update_last_applied_manifest_list_from_resp(manifest_item, schema_item, resp_item)
        elif isinstance(schema_item, dict) and isinstance(resp_item, dict):
            if not isinstance(manifest_item, dict):
                last_applied_manifest[i] = {}
                manifest_item = last_applied_manifest[i]
            update_last_applied_manifest_dict_from_resp(manifest_item, schema_item, resp_item)
        else:
            if manifest_item is None:
                last_applied_manifest[i] = resp_item
    return last_applied_manifest

