def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        return {}

    manifest = app.spec.manifest
    if not manifest:
        return {}

    observer_schemas = {}
    for resource in manifest:
        if not hasattr(resource, 'kind') or not hasattr(resource, 'metadata'):
            continue
        kind = resource.kind
        name = resource.metadata.name if hasattr(resource.metadata, 'name') else None
        if not kind or not name:
            continue
        # Check if a custom observer schema is already specified
        if hasattr(app.spec, 'observer_schemas') and app.spec.observer_schemas:
            key = f"{kind}/{name}"
            if key in app.spec.observer_schemas:
                continue
        # Generate default observer schema
        observer_schemas[f"{kind}/{name}"] = {
            "kind": kind,
            "name": name,
            "status": "Unknown"
        }
    return observer_schemas

