def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        raise ValueError(f"version {version} not found in inventory")

    version_data = inventory[version]
    if not isinstance(version_data, dict):
        raise TypeError(f"inventory[{version}] must be a dictionary")

    # Assume version_data has a key 'files' or similar structure
    # We need to infer the structure. Let's assume:
    # inventory[version] is a dict with key 'files' which is a list of dicts
    # each dict has 'logical_path' and 'content_file' (or similar)

    # Since the exact structure is not specified, we need to make reasonable assumptions.
    # Let's assume the structure is:
    # inventory = {
    #     version: {
    #         'files': [
    #             {'logical_path': 'path1', 'content_file': 'file1'},
    #             {'logical_path': 'path2', 'content_file': 'file2'},
    #         ]
    #     }
    # }

    # But it could also be that version_data directly maps logical paths to content files.
    # Let's handle both cases.

    logical_path_map = {}

    # Case 1: version_data is a dict mapping logical_path -> content_file (or list of content_files)
    if 'files' in version_data:
        files = version_data['files']
        if not isinstance(files, list):
            raise TypeError(f"inventory[{version}]['files'] must be a list")
        for file_entry in files:
            if not isinstance(file_entry, dict):
                continue
            logical_path = file_entry.get('logical_path')
            content_file = file_entry.get('content_file')
            if logical_path is None or content_file is None:
                continue
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)
    else:
        # Case 2: version_data directly maps logical_path -> content_file or list
        for logical_path, content in version_data.items():
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            if isinstance(content, (list, tuple, set)):
                logical_path_map[logical_path].update(content)
            else:
                logical_path_map[logical_path].add(content)

    return logical_path_map

