def _explore_zipfile(zip_path):
    import zipfile
    import os
    import xml.etree.ElementTree as ET

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.is_dir():
                    continue
                file_name = file_info.filename
                # Skip files that are not XML
                if not file_name.lower().endswith('.xml'):
                    continue
                # Get the basename without extension
                base_name = os.path.splitext(os.path.basename(file_name))[0]
                # Read the file content
                with zip_ref.open(file_info) as f:
                    content = f.read()
                # Parse the XML content
                try:
                    root = ET.fromstring(content)
                except ET.ParseError:
                    # If XML parsing fails, store the raw content or skip
                    # For now, store the raw content as a string
                    if base_name not in result:
                        result[base_name] = []
                    result[base_name].append(content.decode('utf-8', errors='ignore'))
                    continue
                # Store the parsed XML element
                if base_name not in result:
                    result[base_name] = []
                result[base_name].append(root)
    except Exception as e:
        # If any error occurs, return an empty dict or handle as needed
        # For robustness, return empty dict on error
        return {}
    return result

