def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Check if the root exists and is valid
    if not hasattr(self, 'root') or self.root is None:
        if show_warnings:
            print("Warning: No root object found.")
        return num_objects, good_objects

    # Validate the root object
    if validate_objects:
        try:
            if self.root.validate():
                good_objects += 1
            num_objects += 1
        except Exception as e:
            if show_warnings:
                print(f"Warning: Error validating root object: {e}")
            num_objects += 1

    # Check digests if required
    if check_digests:
        try:
            if hasattr(self.root, 'digest') and self.root.digest:
                if self.root.validate_digest():
                    pass  # digest is valid
                else:
                    if show_warnings:
                        print("Warning: Root object digest is invalid.")
        except Exception as e:
            if show_warnings:
                print(f"Warning: Error checking root digest: {e}")

    # Recursively validate child objects if they exist
    if hasattr(self.root, 'children') and self.root.children:
        for child in self.root.children:
            child_num, child_good = self._validate_child(child, validate_objects, check_digests, show_warnings)
            num_objects += child_num
            good_objects += child_good

    return num_objects, good_objects

