    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        return

    # Initialize a dictionary to track content digests that differ from the root inventory
    self._different_content_digests = {}

    for version_dir in version_dirs:
        # Check if the version directory exists
        if not os.path.isdir(version_dir):
            continue

        # Look for the inventory file in the version directory
        inventory_file = os.path.join(version_dir, "inventory.json")
        if not os.path.isfile(inventory_file):
            continue

        # Load the inventory file
        try:
            with open(inventory_file, 'r') as f:
                version_inventory = json.load(f)
        except (json.JSONDecodeError, IOError):
            continue

        # Compare with the root inventory if it exists
        if hasattr(self, '_root_inventory') and self._root_inventory:
            for key, value in version_inventory.items():
                if key in self._root_inventory:
                    if self._root_inventory[key] != value:
                        self._different_content_digests[key] = value
                else:
                    # Key not in root inventory, record it
                    self._different_content_digests[key] = value

