    import re

    # Check if path exists
    if not os.path.exists(path):
        return "path does not exist"

    # Check if it's a file
    if os.path.isfile(path):
        return "file"

    # Check if it's a directory
    if not os.path.isdir(path):
        return "not a directory"

    # List directory contents
    try:
        entries = os.listdir(path)
    except Exception as e:
        return f"error listing directory: {str(e)}"

    # Check for OCFL Storage Root: must have a 0= directory
    has_0_dir = False
    for entry in entries:
        if entry == "0":
            has_0_dir = True
            break

    if has_0_dir:
        # Check if 0 directory contains a file matching 0=*.json (Namaste file)
        try:
            zero_entries = os.listdir(os.path.join(path, "0"))
        except Exception:
            zero_entries = []

        namaste_pattern = re.compile(r'^0=.*\.json$')
        has_namaste = any(namaste_pattern.match(e) for e in zero_entries)

        if has_namaste:
            return "root"
        else:
            # Has 0 directory but no Namaste file - might be an object or error
            # Check if it looks like an object: has 0=*.json directly in this directory
            namaste_in_current = any(namaste_pattern.match(e) for e in entries)
            if namaste_in_current:
                return "object"
            else:
                return "directory with 0 subdirectory but no Namaste file"

    # Check if it looks like an OCFL Object: has a 0=*.json file directly
    namaste_pattern = re.compile(r'^0=.*\.json$')
    has_namaste_in_current = any(namaste_pattern.match(e) for e in entries)

    if has_namaste_in_current:
        return "object"

    # If none of the above, return a descriptive error
    return "directory without OCFL indicators"

