def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed = {}
    remaining = list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            # Try to parse the arguments with this subparser
            # We need to handle the case where the subparser might not claim all arguments
            # Use parse_known_args to get both parsed and remaining
            namespace, remaining_args = parser.parse_known_args(remaining)
            # If the subparser successfully parsed at least one argument (or all), record it
            # But we need to be careful: parse_known_args might return an empty namespace
            # if no arguments matched. We should only record if it actually consumed some arguments.
            # However, the problem says "give each requested action's subparser a shot at parsing all arguments"
            # and "remaining arguments not claimed by any subparser".
            # 
            # The key insight: we should only record the subparser if it actually claimed some arguments.
            # How to determine if it claimed arguments? If the length of remaining_args is less than 
            # the length of remaining, then it claimed some.
            if len(remaining_args) < len(remaining):
                parsed[name] = namespace
                remaining = remaining_args
        except SystemExit:
            # argparse raises SystemExit on error, we should catch it and skip this subparser
            continue
        except Exception:
            # Catch any other exceptions and skip this subparser
            continue

    return (parsed, remaining)

