def deep_merge_nodes(nodes):
    def _deep_merge_mapping(existing, new):
        # Create a new MappingNode with merged values
        merged_value = []
        seen_keys = set()

        # First, add all existing entries
        for key_node, value_node in existing.value:
            merged_value.append((key_node, value_node))
            seen_keys.add(key_node.value)

        # Then, add new entries that don't exist in existing
        for key_node, value_node in new.value:
            if key_node.value not in seen_keys:
                merged_value.append((key_node, value_node))
                seen_keys.add(key_node.value)
            else:
                # If key exists, we need to deep merge the values
                # Find the existing entry and replace it with merged value
                for i, (existing_key, existing_val) in enumerate(merged_value):
                    if existing_key.value == key_node.value:
                        # Deep merge the values
                        if hasattr(existing_val, 'value') and hasattr(value_node, 'value') and \
                           isinstance(existing_val.value, list) and isinstance(value_node.value, list):
                            merged_value[i] = (existing_key, _deep_merge_mapping(existing_val, value_node))
                        else:
                            # Last value wins
                            merged_value[i] = (existing_key, value_node)
                        break

        # Create a new MappingNode with the same tag as existing
        from ruamel.yaml.nodes import MappingNode
        return MappingNode(tag=existing.tag, value=merged_value)
    if not nodes:
        return []

    merged = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = value_node
            order.append(key)
        else:
            existing = merged[key]
            # Check if both are MappingNode
            if hasattr(existing, 'value') and hasattr(value_node, 'value') and \
               isinstance(existing.value, list) and isinstance(value_node.value, list):
                # Both are mapping nodes, deep merge
                merged[key] = _deep_merge_mapping(existing, value_node)
            else:
                # Last value wins
                merged[key] = value_node

    return [(key_node, merged[key_node.value]) for key_node, _ in nodes if key_node.value in merged]

