    remaining = list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            # Try to parse the arguments with this subparser
            # We need to handle the case where the subparser might not claim all arguments
            # Use parse_known_args to get both parsed and remaining
            namespace, remaining_args = parser.parse_known_args(remaining)
            # If the subparser successfully parsed at least one argument (or all), record it
            # But we need to be careful: parse_known_args might parse nothing if no known args
            # We should check if any arguments were actually consumed
            # A simple heuristic: if the length of remaining_args is less than remaining,
            # then some arguments were consumed
            if len(remaining_args) < len(remaining):
                parsed[name] = namespace
                remaining = remaining_args
        except SystemExit:
            # argparse raises SystemExit on error, we should catch it and continue
            # This subparser failed to parse, so we skip it
            continue
        except Exception:
            # Catch any other exceptions
            continue

    return (parsed, remaining)

