def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re

    import sys

    import shlex
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX: use shlex.split
        return shlex.split(s)
    elif platform == 0:
        # Windows/CMD: use a regex-based approach
        # This is a simplified version that handles common cases
        # For a more robust implementation, one might use a proper parser
        # Here we use a regex that handles quoted strings and escapes
        # This is a basic implementation that may not handle all edge cases
        # For production use, consider using a more robust parser

        # Pattern to match:
        # - Quoted strings (single or double quotes)
        # - Escaped characters
        # - Unquoted tokens
        pattern = r'(?:"([^"]*)"|\'([^\']*)\'|\\(.)|(\S+))'
        result = []
        for match in re.finditer(pattern, s):
            if match.group(1) is not None:
                result.append(match.group(1))
            elif match.group(2) is not None:
                result.append(match.group(2))
            elif match.group(3) is not None:
                result.append(match.group(3))
            elif match.group(4) is not None:
                result.append(match.group(4))
        return result
    else:
        raise ValueError(f"Unsupported platform: {platform}")

