def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    if not host:
        return False

    # Check if host is a string
    if not isinstance(host, str):
        return False

    # Check for common localhost representations
    if host in ('localhost', '127.0.0.1', '::1', '0.0.0.0'):
        return True

    # Try to resolve the hostname
    try:
        # Get all address info for the host
        addr_info = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            # Check if the IP is a loopback address
            if ip in ('127.0.0.1', '::1', '0.0.0.0'):
                return True
            # Check if it's in the 127.0.0.0/8 range
            if ip.startswith('127.'):
                return True
            # Check if it's the IPv6 loopback
            if ip == '::1':
                return True
    except socket.gaierror:
        # If we can't resolve the host, it's not localhost
        return False
    except Exception:
        return False

    return False

