def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    import sys
    if isinstance(commands, str):
        commands = [commands]

    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    full_command = list(commands) + list(args)

    if verbose:
        print("Running command: " + " ".join(full_command))

    try:
        if hide_stderr:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        else:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        if verbose:
            if result.stdout:
                print(result.stdout.decode('utf-8', errors='replace'))
            if result.stderr and not hide_stderr:
                print(result.stderr.decode('utf-8', errors='replace'), file=sys.stderr)

        return result
    except FileNotFoundError:
        raise
    except Exception as e:
        raise

