def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    if not document or not isinstance(document, str):
        return {}

    document = document.strip()
    if not document:
        return {}

    # Try JSON first
    if document.startswith('{'):
        try:
            data = json.loads(document)
            if isinstance(data, dict):
                return data
        except (json.JSONDecodeError, ValueError):
            pass

    # Try XRD (XML)
    if document.startswith('<'):
        try:
            root = ElementTree.fromstring(document)
            result = {}
            # XRD structure: <XRD><subject>...</subject><alias>...</alias><link>...</link></XRD>
            # We need to extract subject, alias, and links
            ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd'}

            # Try with namespace
            subject_elem = root.find('xrd:subject', ns)
            if subject_elem is None:
                subject_elem = root.find('subject')
            if subject_elem is not None and subject_elem.text:
                result['subject'] = subject_elem.text.strip()

            alias_elem = root.find('xrd:alias', ns)
            if alias_elem is None:
                alias_elem = root.find('alias')
            if alias_elem is not None and alias_elem.text:
                result['alias'] = alias_elem.text.strip()

            links = []
            link_elems = root.findall('xrd:link', ns)
            if not link_elems:
                link_elems = root.findall('link')
            for link in link_elems:
                link_dict = {}
                for attr in ['rel', 'href', 'type', 'template']:
                    val = link.get(attr)
                    if val is not None:
                        link_dict[attr] = val
                if link_dict:
                    links.append(link_dict)
            if links:
                result['links'] = links

            return result
        except ElementTree.ParseError:
            pass

    return {}

