def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xml.etree import ElementTree
    from xml.sax.saxutils import escape

    # Construct the URL for the host-meta document
    url = f"https://{host}/.well-known/host-meta"

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve host-meta document from {host}: {e}")

    # Parse the XML response
    try:
        root = ElementTree.fromstring(response.content)
    except ElementTree.ParseError as e:
        raise Exception(f"Failed to parse host-meta document from {host}: {e}")

    # Create a simple XRD-like object
    class XRD:
        def __init__(self, root):
            self.root = root
            self.links = []
            self.parse()

        def parse(self):
            # Parse the XRD document
            for link in self.root.findall('.//{urn:xmpp:xrd:core:xrd-query:1}Link'):
                self.links.append({
                    'rel': link.get('rel'),
                    'uri': link.get('uri'),
                    'type': link.get('type')
                })

    return XRD(root)

