def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(key, (str, int, float, bool, tuple)):
        raise TypeError("key must be a hashable type")
    if not keys:
        dic[key] = val
        return dic
    if key not in dic:
        dic[key] = {}
    if not isinstance(dic[key], dict):
        raise TypeError(f"Existing value at key '{key}' is not a dictionary, cannot insert nested key")
    return dict_insert(dic[key], val, *keys)

