def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        return parser_dict

    include_key = 'include'
    if include_key not in parser_dict:
        return parser_dict

    include_value = parser_dict[include_key]
    if not isinstance(include_value, dict):
        return parser_dict

    # Process each group in the include dict
    for group_name, group_spec in include_value.items():
        if not isinstance(group_spec, dict):
            continue

        # If the group spec has an 'include' key, resolve it recursively
        if 'include' in group_spec:
            group_spec = self._include_groups(group_spec)

        # Merge the resolved group spec into the main parser_dict
        for key, value in group_spec.items():
            if key == 'include':
                continue
            if key in parser_dict and isinstance(parser_dict[key], dict) and isinstance(value, dict):
                # Recursively merge nested dicts
                parser_dict[key] = self._merge_dicts(parser_dict[key], value)
            else:
                parser_dict[key] = value

    # Remove the include key after processing
    del parser_dict[include_key]

    return parser_dict

