def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not hasattr(self, '_parser_option_specs'):
        self._parser_option_specs = {}

    if command_name not in self._parser_option_specs:
        # Try to get the parser for the command
        parser = self.get_parser(command_name)
        if parser is None:
            return []

        # Extract option specs from the parser
        option_specs = []
        for action in parser._actions:
            if action.option_strings:
                option_specs.append({
                    'option_strings': action.option_strings,
                    'dest': action.dest,
                    'default': action.default,
                    'help': action.help,
                    'required': action.required,
                    'nargs': action.nargs,
                    'const': action.const,
                    'type': action.type,
                    'choices': action.choices,
                    'metavar': action.metavar
                })

        self._parser_option_specs[command_name] = option_specs

    return self._parser_option_specs[command_name]

