        elif isinstance(ansible_args, str):
            cmd.append(ansible_args)

    # Add the playbook path
    cmd.append(playbook_path)

    # Execute the command
    try:
        result = ir_plugin.run_command(cmd, workspace=ir_workspace)
        return result
    except Exception as e:
        raise RuntimeError(f"Failed to execute ansible-playbook: {str(e)}")

