def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os
    import tempfile

    # Build the command
    cmd = ['ansible-playbook']

    # Add extra vars if provided
    if vars_dict:
        # Create a temporary file for the vars
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.json') as f:
            json.dump(vars_dict, f)
            vars_file = f.name
        cmd.extend(['-e', '@' + vars_file])

    # Add the cli_args
    cmd.extend(cli_args)

    # Set up environment
    env = os.environ.copy()

    # If ir_workspace is provided, set the workspace directory
    if ir_workspace:
        try:
            workspace_dir = ir_workspace.get_workspace_dir()
            if workspace_dir:
                env['ANSIBLE_WORKSPACE'] = workspace_dir
        except Exception:
            pass

    # If ir_plugin is provided, set plugin-related environment variables
    if ir_plugin:
        try:
            plugin_name = ir_plugin.get_name()
            if plugin_name:
                env['ANSIBLE_PLUGIN'] = plugin_name
        except Exception:
            pass

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            timeout=3600  # 1 hour timeout
        )

        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass

        # Return the result
        return {
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr
        }

    except subprocess.TimeoutExpired:
        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass
        return {
            'returncode': -1,
            'stdout': '',
            'stderr': 'Command timed out'
        }
    except Exception as e:
        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass
        return {
            'returncode': -1,
            'stdout': '',
            'stderr': str(e)
        }

